CREATE TABLE items (
  _id INTEGER PRIMARY KEY,
  zone TEXT NOT NULL,
  value TEXT NOT NULL,
  hint TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  last_used_at TEXT,
  sort_index INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE zone_sort (
  zone TEXT PRIMARY KEY,
  mode TEXT NOT NULL,
  descending INTEGER NOT NULL DEFAULT 0
);





